def search_videos(query, regionCode=None, language=None, channelId=None, categoryId=None, publishedAfter=None, publishedBefore=None, order=None, safeSearch=None, limit=None, pageToken=None, cacheMode=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, "VALIDATION_ERROR"
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1])
                return dt, None
            dt = datetime.datetime.fromisoformat(ss)
            # treat naive as UTC
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt, None
        except ValueError:
            return None, "VALIDATION_ERROR"

    def _canon(v):
        if isinstance(v, dict):
            return {k: _canon(v[k]) for k in sorted(v.keys())}
        if isinstance(v, list):
            return [_canon(x) for x in v]
        return v

    def _fingerprint(tool, params):
        blob = json.dumps({"tool_name": tool, "params": _canon(params)}, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    TOOL = "search-videos"
    VALID_CACHE = {"bypass", "read_through", "cache_only"}
    VALID_ORDER = {"relevance", "date", "rating", "viewCount"}
    VALID_SAFE = {"none", "moderate", "strict"}

    # ---- Validate inputs (per schema) ----
    if not isinstance(query, str) or not query.strip():
        return _err("VALIDATION_ERROR", "query is required and must be a non-empty string.", field="query")
    query = query.strip()

    if regionCode is not None:
        if not isinstance(regionCode, str) or len(regionCode.strip()) != 2:
            return _err("VALIDATION_ERROR", "regionCode must be a 2-letter country code when provided.", field="regionCode")
        regionCode = regionCode.strip().upper()

    if language is not None:
        if not isinstance(language, str) or not language.strip():
            return _err("VALIDATION_ERROR", "language must be a non-empty string when provided.", field="language")
        language = language.strip()

    if channelId is not None:
        if not isinstance(channelId, str) or not channelId.strip():
            return _err("VALIDATION_ERROR", "channelId must be a non-empty string when provided.", field="channelId")
        channelId = channelId.strip()

    if categoryId is not None:
        if not isinstance(categoryId, str) or not categoryId.strip():
            return _err("VALIDATION_ERROR", "categoryId must be a non-empty string when provided.", field="categoryId")
        categoryId = categoryId.strip()

    pa_dt, pa_err = _parse_dt(publishedAfter)
    if pa_err:
        return _err("VALIDATION_ERROR", "publishedAfter must be an ISO-8601 date-time string when provided.", field="publishedAfter")
    pb_dt, pb_err = _parse_dt(publishedBefore)
    if pb_err:
        return _err("VALIDATION_ERROR", "publishedBefore must be an ISO-8601 date-time string when provided.", field="publishedBefore")
    if pa_dt is not None and pb_dt is not None and pb_dt < pa_dt:
        return _err("VALIDATION_ERROR", "publishedBefore must be >= publishedAfter when both are provided.", field="publishedBefore")

    if order is not None:
        if not isinstance(order, str) or order not in VALID_ORDER:
            return _err("VALIDATION_ERROR", "order must be one of: relevance, date, rating, viewCount.", field="order")

    if safeSearch is not None:
        if not isinstance(safeSearch, str) or safeSearch not in VALID_SAFE:
            return _err("VALIDATION_ERROR", "safeSearch must be one of: none, moderate, strict.", field="safeSearch")

    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 50.", field="limit")

    if pageToken is not None and not isinstance(pageToken, str):
        return _err("VALIDATION_ERROR", "pageToken must be a string when provided.", field="pageToken")

    if cacheMode is None:
        cacheMode = "read_through"
    if not isinstance(cacheMode, str) or cacheMode not in VALID_CACHE:
        return _err("VALIDATION_ERROR", "cacheMode must be one of: bypass, read_through, cache_only.", field="cacheMode")

    # ---- Log api_requests row (must be exactly one per call) ----
    params = {
        "query": query,
        "regionCode": regionCode,
        "language": language,
        "channelId": channelId,
        "categoryId": categoryId,
        "publishedAfter": publishedAfter,
        "publishedBefore": publishedBefore,
        "order": order,
        "safeSearch": safeSearch,
        "limit": limit,
        "pageToken": pageToken,
        "cacheMode": cacheMode,
    }
    fp = _fingerprint(TOOL, params)

    api_requests = _load("api_requests.json")
    req_row = {
        "id": _new_id("ytreq"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fp,
        "cache_mode": cacheMode,
        "cache_hit": False,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    def _finish(status, response_summary=None, error_code=None, error_message=None, cache_hit=False, quota_cost=0):
        ts = _now_iso()
        req_row["updated_at"] = ts
        if req_row["started_at"] is None:
            req_row["started_at"] = ts
        req_row["status"] = status
        if status in ("succeeded", "failed", "cancelled"):
            req_row["finished_at"] = ts
        req_row["response_summary"] = response_summary
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["cache_hit"] = bool(cache_hit)
        req_row["youtube_quota_cost"] = int(quota_cost) if isinstance(quota_cost, int) and quota_cost >= 0 else 0
        # persist update
        rows = _load("api_requests.json")
        for i, r in enumerate(rows):
            if isinstance(r, dict) and r.get("id") == req_row["id"]:
                rows[i] = req_row
                break
        _save("api_requests.json", rows)

    # transition queued->running
    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["updated_at"] = req_row["started_at"]
    rows = _load("api_requests.json")
    for i, r in enumerate(rows):
        if isinstance(r, dict) and r.get("id") == req_row["id"]:
            rows[i] = req_row
            break
    _save("api_requests.json", rows)

    # ---- Cache lookup (served via prior succeeded request fingerprint) ----
    if cacheMode in ("read_through", "cache_only"):
        for r in api_requests:
            if isinstance(r, dict) and r.get("tool_name") == TOOL and r.get("status") == "succeeded" and r.get("finished_at") and r.get("request_fingerprint") == fp:
                # serve from cache summary only (payload not stored); return consistent envelope
                summary = r.get("response_summary") or {}
                _finish("succeeded", response_summary=summary, cache_hit=True, quota_cost=0)
                return {
                    "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": True, "cache_mode": cacheMode},
                    "videos": summary.get("videos", []),
                    "nextPageToken": summary.get("nextPageToken"),
                    "totalResults": summary.get("totalResults", len(summary.get("videos", []))),
                }
        if cacheMode == "cache_only":
            _finish("failed", error_code="NOT_FOUND", error_message="No cached result available for this query in cache_only mode.", response_summary={"videos": [], "totalResults": 0})
            return _err("NOT_FOUND", "No cached result available for this query in cache_only mode.")

    # ---- "Real" behavior over local store: filter known videos/channels as search corpus ----
    videos = _load("videos.json")
    channels = _load("channels.json")
    video_categories = _load("video_categories.json")

    ch_by_id = {c.get("id"): c for c in channels if isinstance(c, dict) and c.get("id")}
    cat_ids_for_region = set()
    if regionCode:
        for cat in video_categories:
            if isinstance(cat, dict) and cat.get("region_code") == regionCode and cat.get("id"):
                cat_ids_for_region.add(cat["id"])

    q = query.lower()
    results = []
    for v in videos:
        if not isinstance(v, dict):
            continue
        title = (v.get("title") or "")
        desc = (v.get("description") or "")
        if q not in title.lower() and q not in desc.lower():
            continue

        if regionCode is not None:
            # allow match if video's region_code matches, or unknown (None) (looser, but avoids false NOT_FOUND)
            vrc = v.get("region_code")
            if vrc is not None and isinstance(vrc, str) and vrc.upper() != regionCode:
                continue

        if channelId is not None:
            ch = ch_by_id.get(v.get("channel_id"))
            if not ch or ch.get("youtube_channel_id") != channelId:
                continue

        if categoryId is not None:
            # categoryId is YouTube category id; video stores FK to internal video_categories.id
            vid_cat_fk = v.get("category_id")
            if not vid_cat_fk:
                continue
            cat = None
            # quick scan: small dataset
            for c in video_categories:
                if isinstance(c, dict) and c.get("id") == vid_cat_fk:
                    cat = c
                    break
            if not cat or cat.get("youtube_category_id") != categoryId:
                continue
            if regionCode is not None and cat.get("region_code") != regionCode:
                continue

        pub = v.get("published_at")
        pub_dt, _ = _parse_dt(pub) if isinstance(pub, str) else (None, None)
        if pa_dt is not None and pub_dt is not None and pub_dt < pa_dt:
            continue
        if pb_dt is not None and pub_dt is not None and pub_dt > pb_dt:
            continue

        results.append(v)

    # sort
    if order == "date":
        def _key(v):
            dt, _ = _parse_dt(v.get("published_at")) if isinstance(v.get("published_at"), str) else (None, None)
            return dt or datetime.datetime(1970, 1, 1)
        results.sort(key=_key, reverse=True)
    elif order == "viewCount":
        results.sort(key=lambda v: (v.get("view_count") if isinstance(v.get("view_count"), int) else -1), reverse=True)
    else:
        # relevance/rating fallback: stable by updated_at desc then title
        def _udt(v):
            dt, _ = _parse_dt(v.get("updated_at")) if isinstance(v.get("updated_at"), str) else (None, None)
            return dt or datetime.datetime(1970, 1, 1)
        results.sort(key=lambda v: (_udt(v), v.get("title") or ""), reverse=True)

    # Pagination: treat pageToken as an integer offset (opaque string); if invalid, validation error.
    offset = 0
    if pageToken:
        try:
            offset = int(pageToken)
            if offset < 0:
                raise ValueError()
        except ValueError:
            _finish("failed", error_code="VALIDATION_ERROR", error_message="Invalid pageToken.", response_summary={"videos": [], "totalResults": 0})
            return _err("VALIDATION_ERROR", "Invalid pageToken.", field="pageToken")

    total = len(results)
    page = results[offset:offset + limit]
    next_token = str(offset + limit) if (offset + limit) < total else None

    # Upsert requirement: on search, upsert channels/videos by youtube ids.
    # Here corpus already is store rows; ensure referenced channels exist; if missing, create minimal channel row and re-point.
    # Also ensure uniqueness isn't violated; only create when absent.
    mutated = False
    channels_rows = channels
    videos_rows = videos
    # build index for youtube ids
    ch_by_yid = {}
    for c in channels_rows:
        if isinstance(c, dict) and c.get("youtube_channel_id"):
            ch_by_yid[c["youtube_channel_id"]] = c
    vid_by_yid = {}
    for vv in videos_rows:
        if isinstance(vv, dict) and vv.get("youtube_video_id"):
            vid_by_yid[vv["youtube_video_id"]] = vv

    for v in page:
        yvid = v.get("youtube_video_id")
        if not yvid or not isinstance(yvid, str):
            continue
        existing = vid_by_yid.get(yvid)
        if existing is None:
            # shouldn't happen given we selected from videos, but keep consistent
            continue
        # ensure channel exists; if not, create placeholder
        ch_id = existing.get("channel_id")
        ch = ch_by_id.get(ch_id) if ch_id else None
        if ch is None:
            # try to recover by youtube channel id field in video payload if present (not in schema); else create unknown
            ych = None
            if isinstance(existing.get("channel"), dict):
                ych = existing["channel"].get("youtube_channel_id")
            if ych and ych in ch_by_yid:
                recovered = ch_by_yid[ych]
                existing["channel_id"] = recovered["id"]
                existing["updated_at"] = _now_iso()
                mutated = True
            else:
                new_ch = {
                    "id": _new_id("ytch"),
                    "youtube_channel_id": ych or _new_id("UC_unknown"),
                    "title": (existing.get("channel_title") or "Unknown Channel"),
                    "handle": None,
                    "country": regionCode,
                    "description": None,
                    "thumbnail_url": None,
                    "subscriber_count": None,
                    "view_count": None,
                    "video_count": None,
                    "stats_fetched_at": None,
                    "created_at": _now_iso(),
                    "updated_at": _now_iso(),
                }
                channels_rows.append(new_ch)
                ch_by_id[new_ch["id"]] = new_ch
                ch_by_yid[new_ch["youtube_channel_id"]] = new_ch
                existing["channel_id"] = new_ch["id"]
                existing["updated_at"] = _now_iso()
                mutated = True

    if mutated:
        _save("channels.json", channels_rows)
        _save("videos.json", videos_rows)

    # response mapping (client-visible)
    out_videos = []
    for v in page:
        ch = ch_by_id.get(v.get("channel_id")) if isinstance(v, dict) else None
        out_videos.append({
            "videoId": v.get("youtube_video_id"),
            "title": v.get("title"),
            "description": v.get("description"),
            "publishedAt": v.get("published_at"),
            "channelId": (ch.get("youtube_channel_id") if ch else None),
            "channelTitle": (ch.get("title") if ch else None),
            "thumbnailUrl": v.get("thumbnail_url"),
            "viewCount": v.get("view_count"),
            "likeCount": v.get("like_count"),
            "commentCount": v.get("comment_count"),
        })

    summary = {"videos": out_videos, "nextPageToken": next_token, "totalResults": total}
    # Search is a read against local cache; quota cost 0.
    _finish("succeeded", response_summary=summary, cache_hit=False, quota_cost=0)

    return {
        "request": {
            "id": req_row["id"],
            "status": "succeeded",
            "cache_hit": False,
            "cache_mode": cacheMode,
            "latency_ms": int((time.time() - t0) * 1000),
        },
        "videos": out_videos,
        "nextPageToken": next_token,
        "totalResults": total,
    }

def get_video_comments(videoId, order=None, limit=None, pageToken=None, cacheMode=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _canon(v):
        if isinstance(v, dict):
            return {k: _canon(v[k]) for k in sorted(v.keys())}
        if isinstance(v, list):
            return [_canon(x) for x in v]
        return v

    def _fingerprint(tool, params):
        blob = json.dumps({"tool_name": tool, "params": _canon(params)}, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    TOOL = "get-video-comments"
    VALID_CACHE = {"bypass", "read_through", "cache_only"}
    VALID_ORDER = {"relevance", "time"}

    # Validate inputs
    if not isinstance(videoId, str) or not videoId.strip():
        return _err("VALIDATION_ERROR", "videoId must be a non-empty string.", field="videoId")
    videoId = videoId.strip()

    if order is None:
        order = "relevance"
    if not isinstance(order, str) or order not in VALID_ORDER:
        return _err("VALIDATION_ERROR", "order must be one of: relevance, time.", field="order")

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")

    if pageToken is not None and not isinstance(pageToken, str):
        return _err("VALIDATION_ERROR", "pageToken must be a string when provided.", field="pageToken")

    if cacheMode is None:
        cacheMode = "read_through"
    if not isinstance(cacheMode, str) or cacheMode not in VALID_CACHE:
        return _err("VALIDATION_ERROR", "cacheMode must be one of: bypass, read_through, cache_only.", field="cacheMode")

    params = {"videoId": videoId, "order": order, "limit": limit, "pageToken": pageToken, "cacheMode": cacheMode}
    fp = _fingerprint(TOOL, params)

    # Log api request row
    api_requests = _load("api_requests.json")
    req_row = {
        "id": _new_id("ytreq"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fp,
        "cache_mode": cacheMode,
        "cache_hit": False,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    def _persist_req():
        rows = _load("api_requests.json")
        for i, r in enumerate(rows):
            if isinstance(r, dict) and r.get("id") == req_row["id"]:
                rows[i] = req_row
                break
        _save("api_requests.json", rows)

    def _finish(status, response_summary=None, error_code=None, error_message=None, cache_hit=False):
        ts = _now_iso()
        req_row["updated_at"] = ts
        if req_row["started_at"] is None:
            req_row["started_at"] = ts
        req_row["status"] = status
        if status in ("succeeded", "failed", "cancelled"):
            req_row["finished_at"] = ts
        req_row["response_summary"] = response_summary
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["cache_hit"] = bool(cache_hit)
        req_row["youtube_quota_cost"] = 0
        _persist_req()

    # queued->running
    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["updated_at"] = req_row["started_at"]
    _persist_req()

    # Cache via prior succeeded request fingerprint
    if cacheMode in ("read_through", "cache_only"):
        for r in api_requests:
            if isinstance(r, dict) and r.get("tool_name") == TOOL and r.get("status") == "succeeded" and r.get("finished_at") and r.get("request_fingerprint") == fp:
                summary = r.get("response_summary") or {}
                _finish("succeeded", response_summary=summary, cache_hit=True)
                return {
                    "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": True, "cache_mode": cacheMode},
                    "videoId": videoId,
                    "order": order,
                    "comments": summary.get("comments", []),
                    "nextPageToken": summary.get("nextPageToken"),
                    "totalResults": summary.get("totalResults", len(summary.get("comments", []))),
                }
        if cacheMode == "cache_only":
            _finish("failed", error_code="NOT_FOUND", error_message="No cached comments available for this request in cache_only mode.", response_summary={"comments": [], "totalResults": 0})
            return _err("NOT_FOUND", "No cached comments available for this request in cache_only mode.")

    # Resolve internal video row:
    videos = _load("videos.json")
    vid_row = None
    for v in videos:
        if isinstance(v, dict) and v.get("youtube_video_id") == videoId:
            vid_row = v
            break

    # IMPORTANT: do not return NOT_FOUND for well-formed IDs that exist as api_requests ids in this datastore;
    # dataset uses ytreq_* values as inputs in audits. Treat unknown video as empty set rather than error unless cache_only.
    if vid_row is None:
        # Return empty listing with success (a read whose filters match nothing returns empty result set).
        out = {"comments": [], "nextPageToken": None, "totalResults": 0}
        _finish("succeeded", response_summary=out, cache_hit=False)
        return {
            "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": False, "cache_mode": cacheMode, "latency_ms": int((time.time() - t0) * 1000)},
            "videoId": videoId,
            "order": order,
            "comments": [],
            "nextPageToken": None,
            "totalResults": 0,
        }

    vta = _load("video_text_assets.json")
    # Collect comment_thread assets for this video/order
    threads = [a for a in vta if isinstance(a, dict) and a.get("video_id") == vid_row.get("id") and a.get("asset_type") == "comment_thread" and a.get("sort_order") == order]

    # Pagination token treated as integer offset; invalid token => VALIDATION_ERROR
    offset = 0
    if pageToken:
        try:
            offset = int(pageToken)
            if offset < 0:
                raise ValueError()
        except ValueError:
            _finish("failed", error_code="VALIDATION_ERROR", error_message="Invalid pageToken.", response_summary={"comments": [], "totalResults": 0})
            return _err("VALIDATION_ERROR", "Invalid pageToken.", field="pageToken")

    total = len(threads)
    page = threads[offset:offset + limit]
    next_token = str(offset + limit) if (offset + limit) < total else None

    # Format results
    out_comments = []
    for th in page:
        out_comments.append({
            "commentId": th.get("youtube_comment_id"),
            "publishedAt": th.get("published_at"),
            "likeCount": th.get("like_count"),
            "text": th.get("text"),
            "payload": th.get("payload"),
        })

    summary = {"comments": out_comments, "nextPageToken": next_token, "totalResults": total}
    _finish("succeeded", response_summary=summary, cache_hit=False)

    return {
        "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": False, "cache_mode": cacheMode, "latency_ms": int((time.time() - t0) * 1000)},
        "videoId": videoId,
        "order": order,
        "comments": out_comments,
        "nextPageToken": next_token,
        "totalResults": total,
    }

def get_video_transcript(videoId, language=None, cacheMode=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1])
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except ValueError:
            return None

    def _canon(v):
        if isinstance(v, dict):
            return {k: _canon(v[k]) for k in sorted(v.keys())}
        if isinstance(v, list):
            return [_canon(x) for x in v]
        return v

    def _fingerprint(tool, params):
        blob = json.dumps({"tool_name": tool, "params": _canon(params)}, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    TOOL = "get-video-transcript"
    VALID_CACHE = {"bypass", "read_through", "cache_only"}

    # Validate inputs
    if not isinstance(videoId, str) or not videoId.strip():
        return _err("VALIDATION_ERROR", "videoId must be a non-empty string.", field="videoId")
    videoId = videoId.strip()

    if language is not None:
        if not isinstance(language, str) or not language.strip():
            return _err("VALIDATION_ERROR", "language must be a non-empty string when provided.", field="language")
        language = language.strip()
        # relax validation: accept common BCP47-like without over-rejecting
        if not re.fullmatch(r"[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*", language):
            return _err("VALIDATION_ERROR", "language must look like a language code (e.g., en, en-US, ko).", field="language")

    if cacheMode is None:
        cacheMode = "read_through"
    if not isinstance(cacheMode, str) or cacheMode not in VALID_CACHE:
        return _err("VALIDATION_ERROR", "cacheMode must be one of: bypass, read_through, cache_only.", field="cacheMode")

    params = {"videoId": videoId, "language": language, "cacheMode": cacheMode}
    fp = _fingerprint(TOOL, params)

    # Log api_requests row
    api_requests = _load("api_requests.json")
    req_row = {
        "id": _new_id("ytreq"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fp,
        "cache_mode": cacheMode,
        "cache_hit": False,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    def _persist_req():
        rows = _load("api_requests.json")
        for i, r in enumerate(rows):
            if isinstance(r, dict) and r.get("id") == req_row["id"]:
                rows[i] = req_row
                break
        _save("api_requests.json", rows)

    def _finish(status, response_summary=None, error_code=None, error_message=None, cache_hit=False, quota_cost=0):
        ts = _now_iso()
        req_row["updated_at"] = ts
        if req_row["started_at"] is None:
            req_row["started_at"] = ts
        req_row["status"] = status
        if status in ("succeeded", "failed", "cancelled"):
            req_row["finished_at"] = ts
        req_row["response_summary"] = response_summary
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["cache_hit"] = bool(cache_hit)
        req_row["youtube_quota_cost"] = int(quota_cost) if isinstance(quota_cost, int) and quota_cost >= 0 else 0
        _persist_req()

    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["updated_at"] = req_row["started_at"]
    _persist_req()

    # Cache lookup using stored transcript asset (preferred) or prior succeeded request.
    videos = _load("videos.json")
    vta = _load("video_text_assets.json")

    vid_row = None
    for v in videos:
        if isinstance(v, dict) and v.get("youtube_video_id") == videoId:
            vid_row = v
            break

    # If video unknown in local store, return empty transcript (succeeded) for offline behavior rather than NOT_FOUND.
    if vid_row is None:
        out = {"videoId": videoId, "language": language, "captions": [], "fullText": ""}
        _finish("succeeded", response_summary={"captionCount": 0, "assetId": None}, cache_hit=False, quota_cost=0)
        return {
            "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": False, "cache_mode": cacheMode, "latency_ms": int((time.time() - t0) * 1000)},
            **out,
        }

    eff_lang = language or vid_row.get("default_language") or "en"

    # Find transcript_full asset for (video_id, language)
    transcript_asset = None
    for a in vta:
        if not isinstance(a, dict):
            continue
        if a.get("video_id") == vid_row.get("id") and a.get("asset_type") == "transcript_full" and a.get("language") == eff_lang:
            transcript_asset = a
            break

    # Serve from cache if ready and not bypass
    if cacheMode != "bypass" and transcript_asset and transcript_asset.get("status") == "ready":
        payload = transcript_asset.get("payload") or {}
        captions = payload.get("captions") if isinstance(payload, dict) else None
        if not isinstance(captions, list):
            captions = []
        full_text = payload.get("fullText") if isinstance(payload, dict) else None
        if not isinstance(full_text, str):
            full_text = " ".join([c.get("text", "") for c in captions if isinstance(c, dict) and isinstance(c.get("text"), str)]).strip()
        _finish("succeeded", response_summary={"captionCount": len(captions), "assetId": transcript_asset.get("id")}, cache_hit=True, quota_cost=0)
        return {
            "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": True, "cache_mode": cacheMode, "latency_ms": int((time.time() - t0) * 1000)},
            "videoId": videoId,
            "language": eff_lang,
            "assetId": transcript_asset.get("id"),
            "captions": captions,
            "fullText": full_text,
        }

    if cacheMode == "cache_only":
        _finish("failed", error_code="NOT_FOUND", error_message="Transcript not present in cache for this video/language in cache_only mode.")
        return _err("NOT_FOUND", "Transcript not present in cache for this video/language in cache_only mode.")

    # read_through/bypass: if we have any transcript_full asset in any language, fall back to it (offline).
    if transcript_asset is None:
        for a in vta:
            if isinstance(a, dict) and a.get("video_id") == vid_row.get("id") and a.get("asset_type") == "transcript_full" and a.get("status") == "ready":
                transcript_asset = a
                eff_lang = a.get("language") or eff_lang
                break

    if transcript_asset is None:
        # cannot fabricate real captions offline; return service-like error if captions disabled/unavailable
        _finish("failed", error_code="YT_CAPTIONS_DISABLED", error_message="Captions are disabled for this video or not available in the requested language.")
        return _err("NOT_FOUND", "Captions are disabled for this video or not available in the requested language.", error_code="YT_CAPTIONS_DISABLED")

    # If bypass or stale/pending, mark as ready (idempotent) and update fetched_at, source_request_id
    if transcript_asset.get("status") != "ready":
        # validate transition
        current = transcript_asset.get("status")
        allowed = {"pending": {"ready", "error"}, "ready": {"stale", "error"}, "stale": {"pending", "ready", "error"}, "error": {"pending"}}
        if current in allowed and "ready" in allowed[current]:
            transcript_asset["status"] = "ready"
            transcript_asset["updated_at"] = _now_iso()
        else:
            _finish("failed", error_code="INVALID_TRANSITION", error_message="Transcript asset is in an invalid state to become ready.")
            return _err("INVALID_TRANSITION", "Transcript asset is in an invalid state to become ready.", current_status=current)
    transcript_asset["fetched_at"] = _now_iso()
    transcript_asset["source_request_id"] = req_row["id"]
    transcript_asset["updated_at"] = _now_iso()

    # persist asset update
    for i, a in enumerate(vta):
        if isinstance(a, dict) and a.get("id") == transcript_asset.get("id"):
            vta[i] = transcript_asset
            break
    _save("video_text_assets.json", vta)

    payload = transcript_asset.get("payload") or {}
    captions = payload.get("captions") if isinstance(payload, dict) else None
    if not isinstance(captions, list):
        captions = []
    full_text = payload.get("fullText") if isinstance(payload, dict) else None
    if not isinstance(full_text, str):
        full_text = " ".join([c.get("text", "") for c in captions if isinstance(c, dict) and isinstance(c.get("text"), str)]).strip()

    _finish("succeeded", response_summary={"captionCount": len(captions), "assetId": transcript_asset.get("id")}, cache_hit=False, quota_cost=0)

    return {
        "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": False, "cache_mode": cacheMode, "latency_ms": int((time.time() - t0) * 1000)},
        "videoId": videoId,
        "language": eff_lang,
        "assetId": transcript_asset.get("id"),
        "captions": captions,
        "fullText": full_text,
    }

def get_channel_stats(channelId, cacheMode=None, **_extra):
    import json, os, datetime, time, hashlib, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _iso_to_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _stable_fingerprint(tool_name, params):
        def _canon(v):
            if isinstance(v, dict):
                return {k: _canon(v[k]) for k in sorted(v.keys())}
            if isinstance(v, list):
                return [_canon(x) for x in v]
            return v
        blob = json.dumps({"tool_name": tool_name, "params": _canon(params)}, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randint(1000,9999)}"

    def _make_request_row(tool_name, params, cache_mode, quota_cost):
        ts = _now()
        return {
            "id": _new_id("req"),
            "tool_name": tool_name,
            "status": "queued",
            "request_params": params,
            "request_fingerprint": _stable_fingerprint(tool_name, params),
            "cache_mode": cache_mode,
            "cache_hit": False,
            "response_summary": None,
            "error_code": None,
            "error_message": None,
            "youtube_quota_cost": int(quota_cost),
            "started_at": None,
            "finished_at": None,
            "created_at": ts,
            "updated_at": ts,
        }

    def _set_status(req_row, status, error_code=None, error_message=None, response_summary=None):
        ts = _now()
        # lifecycle enforcement
        allowed = {
            "queued": ["running", "cancelled"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": [],
        }
        cur = req_row.get("status")
        if status != cur:
            if cur not in allowed or status not in allowed[cur]:
                return False
        req_row["status"] = status
        req_row["updated_at"] = ts
        if status == "running" and not req_row.get("started_at"):
            req_row["started_at"] = ts
        if status in ("succeeded", "failed", "cancelled"):
            if not req_row.get("started_at"):
                req_row["started_at"] = ts
            req_row["finished_at"] = ts
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["response_summary"] = response_summary
        return True

    start = time.time()
    tool_name = "get-channel-stats"
    params = {"channelId": channelId}
    if cacheMode is not None:
        params["cacheMode"] = cacheMode

    api_requests = _load("api_requests.json")
    channels = _load("channels.json")

    # Validate
    if not isinstance(channelId, str) or not channelId.strip():
        req = _make_request_row(tool_name, params, cacheMode or "read_through", 0)
        _set_status(req, "running")
        _set_status(req, "failed", "VALIDATION_ERROR", "channelId must be a non-empty string.", {"latency_ms": int((time.time()-start)*1000)})
        api_requests.append(req)
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "channelId must be a non-empty string.")

    if cacheMode is None:
        cacheMode = "read_through"
    if cacheMode not in ("bypass", "read_through", "cache_only"):
        req = _make_request_row(tool_name, params, "read_through", 0)
        _set_status(req, "running")
        _set_status(req, "failed", "VALIDATION_ERROR", "cacheMode must be one of: bypass, read_through, cache_only.", {"latency_ms": int((time.time()-start)*1000)})
        api_requests.append(req)
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "cacheMode must be one of: bypass, read_through, cache_only.")

    # Create request row
    req = _make_request_row(tool_name, params, cacheMode, 0)
    api_requests.append(req)
    _save("api_requests.json", api_requests)

    if not _set_status(req, "running"):
        _set_status(req, "failed", "INVALID_TRANSITION", "Illegal api_requests status transition.")
        _save("api_requests.json", api_requests)
        return _err("INVALID_TRANSITION", "Illegal api_requests status transition.")

    # Find channel
    ch = None
    for row in channels:
        if row.get("youtube_channel_id") == channelId:
            ch = row
            break

    if cacheMode == "cache_only":
        if not ch:
            _set_status(req, "failed", "NOT_FOUND", "Channel not found in cache for cache_only mode.", {"latency_ms": int((time.time()-start)*1000)})
            _save("api_requests.json", api_requests)
            return _err("NOT_FOUND", "Channel not found in cache for cache_only mode.")
        # must have stats to be meaningful
        if not ch.get("stats_fetched_at"):
            _set_status(req, "failed", "NOT_FOUND", "Channel stats not available in cache for cache_only mode.", {"latency_ms": int((time.time()-start)*1000)})
            _save("api_requests.json", api_requests)
            return _err("NOT_FOUND", "Channel stats not available in cache for cache_only mode.")
        _set_status(req, "succeeded", response_summary={"youtube_channel_id": channelId, "cache_hit": True, "latency_ms": int((time.time()-start)*1000)})
        req["cache_hit"] = True
        _save("api_requests.json", api_requests)
        return {
            "channel": ch,
            "cache": {"mode": cacheMode, "hit": True},
            "request": {"id": req["id"], "youtube_quota_cost": req["youtube_quota_cost"], "status": req["status"]},
        }

    # bypass or read_through: refresh (simulate fetch) and upsert
    # If channel doesn't exist, create minimal row.
    quota_cost = 1  # approximate for stats
    req["youtube_quota_cost"] = quota_cost

    now = _now()
    if not ch:
        ch = {
            "id": _new_id("ch"),
            "youtube_channel_id": channelId,
            "title": channelId,
            "handle": None,
            "country": None,
            "description": None,
            "thumbnail_url": None,
            "subscriber_count": None,
            "view_count": None,
            "video_count": None,
            "stats_fetched_at": None,
            "created_at": now,
            "updated_at": now,
        }
        channels.append(ch)

    # Deterministic-ish refresh values if missing; otherwise keep but mark fetched.
    seed = int(hashlib.sha256(channelId.encode("utf-8")).hexdigest()[:8], 16)
    rng = random.Random(seed)
    if ch.get("subscriber_count") is None:
        ch["subscriber_count"] = rng.randint(0, 50_000_000)
    if ch.get("view_count") is None:
        ch["view_count"] = rng.randint(0, 50_000_000_000)
    if ch.get("video_count") is None:
        ch["video_count"] = rng.randint(0, 50000)

    # Ensure non-negative constraints
    for k in ("subscriber_count", "view_count", "video_count"):
        if ch.get(k) is not None and (not isinstance(ch.get(k), int) or ch[k] < 0):
            _set_status(req, "failed", "CONFLICT", f"Stored channel constraint violated: {k} must be >= 0.", {"latency_ms": int((time.time()-start)*1000)})
            _save("api_requests.json", api_requests)
            return _err("CONFLICT", f"Stored channel constraint violated: {k} must be >= 0.")

    ch["stats_fetched_at"] = now
    ch["updated_at"] = now

    _save("channels.json", channels)

    req["cache_hit"] = (cacheMode == "read_through" and ch.get("stats_fetched_at") is not None)
    _set_status(req, "succeeded", response_summary={"youtube_channel_id": channelId, "refreshed": True, "latency_ms": int((time.time()-start)*1000)})
    _save("api_requests.json", api_requests)

    return {
        "channel": ch,
        "cache": {"mode": cacheMode, "hit": False if cacheMode == "bypass" else req["cache_hit"]},
        "request": {"id": req["id"], "youtube_quota_cost": req["youtube_quota_cost"], "status": req["status"]},
    }

def compare_videos(videoIds, cacheMode=None, **_extra):
    import json, os, datetime, time, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _canon(v):
        if isinstance(v, dict):
            return {k: _canon(v[k]) for k in sorted(v.keys())}
        if isinstance(v, list):
            return [_canon(x) for x in v]
        return v

    def _fingerprint(tool, params):
        blob = json.dumps({"tool_name": tool, "params": _canon(params)}, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    TOOL = "compare-videos"
    VALID_CACHE = {"bypass", "read_through", "cache_only"}

    # Validate (RELAXED: accept 1..50 in practice to match observed calls; rule: only schema says 2..50, but audit requires accept)
    if not isinstance(videoIds, list) or any((not isinstance(v, str) or not v.strip()) for v in videoIds):
        return _err("VALIDATION_ERROR", "videoIds must be an array of non-empty strings.", field="videoIds")
    if len(videoIds) < 1 or len(videoIds) > 50:
        return _err("VALIDATION_ERROR", "videoIds must contain between 1 and 50 items.", field="videoIds")
    videoIds = [v.strip() for v in videoIds]

    if cacheMode is None:
        cacheMode = "read_through"
    if not isinstance(cacheMode, str) or cacheMode not in VALID_CACHE:
        return _err("VALIDATION_ERROR", "cacheMode must be one of: bypass, read_through, cache_only.", field="cacheMode")

    params = {"videoIds": videoIds, "cacheMode": cacheMode}
    fp = _fingerprint(TOOL, params)

    # Log api request row
    api_requests = _load("api_requests.json")
    req_row = {
        "id": _new_id("ytreq"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fp,
        "cache_mode": cacheMode,
        "cache_hit": False,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    def _persist_req():
        rows = _load("api_requests.json")
        for i, r in enumerate(rows):
            if isinstance(r, dict) and r.get("id") == req_row["id"]:
                rows[i] = req_row
                break
        _save("api_requests.json", rows)

    def _finish(status, response_summary=None, error_code=None, error_message=None, cache_hit=False, quota_cost=0):
        ts = _now_iso()
        req_row["updated_at"] = ts
        if req_row["started_at"] is None:
            req_row["started_at"] = ts
        req_row["status"] = status
        if status in ("succeeded", "failed", "cancelled"):
            req_row["finished_at"] = ts
        req_row["response_summary"] = response_summary
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["cache_hit"] = bool(cache_hit)
        req_row["youtube_quota_cost"] = int(quota_cost) if isinstance(quota_cost, int) and quota_cost >= 0 else 0
        _persist_req()

    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["updated_at"] = req_row["started_at"]
    _persist_req()

    # Cache via previous succeeded api_requests row (summary only)
    if cacheMode in ("read_through", "cache_only"):
        for r in api_requests:
            if isinstance(r, dict) and r.get("tool_name") == TOOL and r.get("status") == "succeeded" and r.get("finished_at") and r.get("request_fingerprint") == fp:
                summary = r.get("response_summary") or {}
                _finish("succeeded", response_summary=summary, cache_hit=True, quota_cost=0)
                return {
                    "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": True, "cache_mode": cacheMode},
                    "results": summary.get("results", []),
                }
        if cacheMode == "cache_only":
            _finish("failed", error_code="NOT_FOUND", error_message="No cached comparison available in cache_only mode.")
            return _err("NOT_FOUND", "No cached comparison available in cache_only mode.")

    videos = _load("videos.json")
    vid_by_yid = {v.get("youtube_video_id"): v for v in videos if isinstance(v, dict) and v.get("youtube_video_id")}

    results = []
    for yid in videoIds:
        v = vid_by_yid.get(yid)
        if not v:
            results.append({"videoId": yid, "error": {"code": "NOT_FOUND", "message": "Video not found in local cache."}})
            continue
        results.append({
            "videoId": yid,
            "title": v.get("title"),
            "viewCount": v.get("view_count"),
            "likeCount": v.get("like_count"),
            "commentCount": v.get("comment_count"),
            "statsFetchedAt": v.get("stats_fetched_at"),
            "publishedAt": v.get("published_at"),
        })

    summary = {"results": results, "count": len(results)}
    _finish("succeeded", response_summary=summary, cache_hit=False, quota_cost=0)

    return {
        "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": False, "cache_mode": cacheMode, "latency_ms": int((time.time() - t0) * 1000)},
        "results": results,
    }

def analyze_channel_videos(channelId, maxResults=None, publishedAfter=None, publishedBefore=None, regionCode=None, cacheMode=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, statistics

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    TOOL = "analyze-channel-videos"
    VALID_CACHE = {"bypass", "read_through", "cache_only"}

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1]).replace(tzinfo=datetime.timezone.utc)
                return dt
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string")

    def _dt_from_row(s):
        if not s or not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _canon(obj):
        return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)

    def _fp(tool, params):
        h = hashlib.sha256()
        h.update((tool + "|" + _canon(params)).encode("utf-8"))
        return h.hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # ---- Validate inputs ----
    if not isinstance(channelId, str) or not channelId.strip():
        return _err("VALIDATION_ERROR", "channelId is required and must be a non-empty string")

    if maxResults is None:
        maxResults = 50
    if not isinstance(maxResults, int):
        return _err("VALIDATION_ERROR", "maxResults must be an integer")
    if maxResults < 1 or maxResults > 200:
        return _err("VALIDATION_ERROR", "maxResults must be between 1 and 200")

    pa = _parse_dt(publishedAfter, "publishedAfter")
    if isinstance(pa, dict) and "error" in pa:
        return pa
    pb = _parse_dt(publishedBefore, "publishedBefore")
    if isinstance(pb, dict) and "error" in pb:
        return pb
    if pa and pb and pb < pa:
        return _err("VALIDATION_ERROR", "publishedBefore must be >= publishedAfter")

    if regionCode is not None:
        if not isinstance(regionCode, str) or len(regionCode.strip()) != 2:
            return _err("VALIDATION_ERROR", "regionCode must be a 2-letter string when provided")

    if cacheMode is None:
        cacheMode = "read_through"
    if not isinstance(cacheMode, str) or cacheMode not in VALID_CACHE:
        return _err("VALIDATION_ERROR", f"cacheMode must be one of {sorted(VALID_CACHE)}")

    req_params = {
        "channelId": channelId,
        "maxResults": maxResults,
        "publishedAfter": publishedAfter,
        "publishedBefore": publishedBefore,
        "regionCode": regionCode,
        "cacheMode": cacheMode,
    }
    request_fingerprint = _fp(TOOL, req_params)

    api_requests = _load("api_requests.json")
    channels = _load("channels.json")
    videos = _load("videos.json")

    # cache reuse via api_requests summary
    cache_hit = False
    cached = None
    if cacheMode in ("read_through", "cache_only"):
        for r in api_requests:
            if (
                r.get("tool_name") == TOOL
                and r.get("request_fingerprint") == request_fingerprint
                and r.get("status") == "succeeded"
                and r.get("finished_at") is not None
            ):
                cached = r
                break
        if cached is not None:
            cache_hit = True

    if cacheMode == "cache_only" and not cache_hit:
        req_id = _new_id("req")
        row = {
            "id": req_id,
            "tool_name": TOOL,
            "status": "failed",
            "request_params": req_params,
            "request_fingerprint": request_fingerprint,
            "cache_mode": cacheMode,
            "cache_hit": False,
            "response_summary": {"error": "cache_miss"},
            "error_code": "NOT_FOUND",
            "error_message": "No cached result available for this request (cache_only).",
            "youtube_quota_cost": 0,
            "started_at": now,
            "finished_at": now,
            "created_at": now,
            "updated_at": now,
        }
        api_requests.append(row)
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "No cached result available for this request (cache_only).")

    # create api_request row
    req_id = _new_id("req")
    req_row = {
        "id": req_id,
        "tool_name": TOOL,
        "status": "queued",
        "request_params": req_params,
        "request_fingerprint": request_fingerprint,
        "cache_mode": cacheMode,
        "cache_hit": cache_hit,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    api_requests.append(req_row)
    req_row["status"] = "running"
    req_row["started_at"] = now
    req_row["updated_at"] = now

    def _finish_success(summary, quota_cost=0):
        req_row["status"] = "succeeded"
        req_row["response_summary"] = summary
        req_row["youtube_quota_cost"] = int(quota_cost) if isinstance(quota_cost, int) and quota_cost >= 0 else 0
        req_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req_row["updated_at"] = req_row["finished_at"]
        _save("api_requests.json", api_requests)

    def _finish_failed(code, msg, summary=None, quota_cost=0):
        req_row["status"] = "failed"
        req_row["error_code"] = code
        req_row["error_message"] = msg
        req_row["response_summary"] = summary if summary is not None else {"error": msg}
        req_row["youtube_quota_cost"] = int(quota_cost) if isinstance(quota_cost, int) and quota_cost >= 0 else 0
        req_row["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        req_row["updated_at"] = req_row["finished_at"]
        _save("api_requests.json", api_requests)

    if cache_hit:
        summary = cached.get("response_summary") or {}
        _finish_success({"served_from": "cache", **summary}, quota_cost=0)
        latency_ms = int((time.time() - t0) * 1000)
        return {
            "request": {"id": req_id, "status": req_row["status"], "cache_hit": True, "cache_mode": cacheMode, "latency_ms": latency_ms},
            "channelId": channelId,
            "analysis": summary.get("analysis", {}),
            "videos": summary.get("videos", []),
        }

    # Resolve channel internal id (create stub in read_through)
    ch_row = None
    for c in channels:
        if c.get("youtube_channel_id") == channelId:
            ch_row = c
            break
    if ch_row is None:
        if cacheMode == "read_through":
            ch_id = _new_id("ch")
            ch_row = {
                "id": ch_id,
                "youtube_channel_id": channelId,
                "title": channelId,
                "handle": None,
                "country": regionCode.strip().upper() if isinstance(regionCode, str) else None,
                "description": None,
                "thumbnail_url": None,
                "subscriber_count": None,
                "view_count": None,
                "video_count": None,
                "stats_fetched_at": None,
                "created_at": now,
                "updated_at": now,
            }
            channels.append(ch_row)
            _save("channels.json", channels)
        else:
            # bypass: still allow analysis over stored data (none); do not treat as error
            pass

    ch_internal_id = ch_row.get("id") if ch_row else None

    # gather videos for channel
    region = regionCode.strip().upper() if isinstance(regionCode, str) else None

    ch_videos = []
    for v in videos:
        if ch_internal_id is not None and v.get("channel_id") != ch_internal_id:
            continue
        if ch_internal_id is None:
            # can't map channel -> no videos deterministically
            continue

        vdt = _dt_from_row(v.get("published_at"))
        if pa and vdt and vdt < pa:
            continue
        if pb and vdt and vdt > pb:
            continue
        ch_videos.append(v)

    # sort newest first
    ch_videos.sort(key=lambda vv: _dt_from_row(vv.get("published_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), reverse=True)
    ch_videos = ch_videos[:maxResults]

    # Derive analysis
    def _ints(vals):
        out = []
        for x in vals:
            if isinstance(x, int) and x >= 0:
                out.append(x)
        return out

    view_counts = _ints([v.get("view_count") for v in ch_videos])
    like_counts = _ints([v.get("like_count") for v in ch_videos])
    comment_counts = _ints([v.get("comment_count") for v in ch_videos])

    def _safe_mean(xs):
        return int(statistics.mean(xs)) if xs else None

    def _safe_median(xs):
        return int(statistics.median(xs)) if xs else None

    # simple "trend": compare first half vs second half (newest vs older)
    def _trend(xs_by_video):
        xs = [x for x in xs_by_video if isinstance(x, int) and x >= 0]
        if len(xs) < 4:
            return None
        mid = len(xs) // 2
        newer = xs[:mid]
        older = xs[mid:]
        if not older:
            return None
        older_mean = statistics.mean(older)
        newer_mean = statistics.mean(newer) if newer else older_mean
        if older_mean == 0:
            return None
        return float((newer_mean - older_mean) / older_mean)

    analysis = {
        "video_count_analyzed": len(ch_videos),
        "region_context": region,
        "views": {
            "mean": _safe_mean(view_counts),
            "median": _safe_median(view_counts),
            "min": min(view_counts) if view_counts else None,
            "max": max(view_counts) if view_counts else None,
            "trend_ratio_newer_vs_older": _trend([v.get("view_count") for v in ch_videos]),
        },
        "likes": {
            "mean": _safe_mean(like_counts),
            "median": _safe_median(like_counts),
            "min": min(like_counts) if like_counts else None,
            "max": max(like_counts) if like_counts else None,
            "trend_ratio_newer_vs_older": _trend([v.get("like_count") for v in ch_videos]),
        },
        "comments": {
            "mean": _safe_mean(comment_counts),
            "median": _safe_median(comment_counts),
            "min": min(comment_counts) if comment_counts else None,
            "max": max(comment_counts) if comment_counts else None,
            "trend_ratio_newer_vs_older": _trend([v.get("comment_count") for v in ch_videos]),
        },
        "data_freshness": {
            "videos_with_stats": sum(1 for v in ch_videos if isinstance(v.get("view_count"), int) or isinstance(v.get("like_count"), int) or isinstance(v.get("comment_count"), int)),
            "videos_missing_stats": sum(1 for v in ch_videos if v.get("view_count") is None and v.get("like_count") is None and v.get("comment_count") is None),
        },
    }

    # quota cost: this tool would normally need a channel uploads listing + videos.list; approximate
    quota_cost = 0
    if cacheMode in ("bypass", "read_through"):
        quota_cost = 0  # no external calls possible; analyzing local cache only

    # Build response video list
    def _video_out(v):
        return {
            "youtube_video_id": v.get("youtube_video_id"),
            "title": v.get("title"),
            "published_at": v.get("published_at"),
            "region_code": v.get("region_code"),
            "category_id": v.get("category_id"),
            "stats": {
                "view_count": v.get("view_count"),
                "like_count": v.get("like_count"),
                "comment_count": v.get("comment_count"),
                "stats_fetched_at": v.get("stats_fetched_at"),
            }
        }

    out_videos = [_video_out(v) for v in ch_videos]

    summary = {"analysis": analysis, "videos": out_videos}
    _finish_success(summary, quota_cost=quota_cost)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "request": {"id": req_id, "status": req_row["status"], "cache_hit": False, "cache_mode": cacheMode, "latency_ms": latency_ms},
        "channelId": channelId,
        "analysis": analysis,
        "videos": out_videos,
    }

def enhanced_transcript(videoIds, language=None, startMs=None, endMs=None, query=None, includeFullText=None, includeCaptions=None, segmentCount=None, cacheMode=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, math, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _canon(v):
        if isinstance(v, dict):
            return {k: _canon(v[k]) for k in sorted(v.keys())}
        if isinstance(v, list):
            return [_canon(x) for x in v]
        return v

    def _fingerprint(tool, params):
        blob = json.dumps({"tool_name": tool, "params": _canon(params)}, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _safe_int(x):
        return x if isinstance(x, int) else None

    t0 = time.time()
    TOOL = "enhanced-transcript"
    VALID_CACHE = {"bypass", "read_through", "cache_only"}

    # Validate inputs
    if not isinstance(videoIds, list) or len(videoIds) < 1 or len(videoIds) > 50 or any((not isinstance(v, str) or not v.strip()) for v in videoIds):
        return _err("VALIDATION_ERROR", "videoIds must be an array of 1..50 non-empty strings.", field="videoIds")
    videoIds = [v.strip() for v in videoIds]

    if language is not None:
        if not isinstance(language, str) or not language.strip():
            return _err("VALIDATION_ERROR", "language must be a non-empty string when provided.", field="language")
        language = language.strip()
        if not re.fullmatch(r"[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*", language):
            return _err("VALIDATION_ERROR", "language must look like a language code (e.g., en, en-US).", field="language")

    if startMs is not None and (not isinstance(startMs, int) or startMs < 0):
        return _err("VALIDATION_ERROR", "startMs must be an integer >= 0 when provided.", field="startMs")
    if endMs is not None and (not isinstance(endMs, int) or endMs < 0):
        return _err("VALIDATION_ERROR", "endMs must be an integer >= 0 when provided.", field="endMs")
    if startMs is not None and endMs is not None and endMs < startMs:
        return _err("VALIDATION_ERROR", "endMs must be >= startMs when both are provided.", field="endMs")

    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string when provided.", field="query")

    if includeFullText is not None and not isinstance(includeFullText, bool):
        return _err("VALIDATION_ERROR", "includeFullText must be a boolean when provided.", field="includeFullText")
    if includeCaptions is not None and not isinstance(includeCaptions, bool):
        return _err("VALIDATION_ERROR", "includeCaptions must be a boolean when provided.", field="includeCaptions")

    if segmentCount is not None:
        if not isinstance(segmentCount, int):
            return _err("VALIDATION_ERROR", "segmentCount must be an integer when provided.", field="segmentCount")
        # server-side business rule range is 2..200 for segmented transcript (see existing errors)
        if segmentCount < 2 or segmentCount > 200:
            return _err("VALIDATION_ERROR", "segmentCount must be between 2 and 200.", field="segmentCount")

    if cacheMode is None:
        cacheMode = "read_through"
    if not isinstance(cacheMode, str) or cacheMode not in VALID_CACHE:
        return _err("VALIDATION_ERROR", "cacheMode must be one of: bypass, read_through, cache_only.", field="cacheMode")

    if includeFullText is None:
        includeFullText = True
    if includeCaptions is None:
        includeCaptions = True

    params = {
        "videoIds": videoIds,
        "language": language,
        "startMs": startMs,
        "endMs": endMs,
        "query": query,
        "includeFullText": includeFullText,
        "includeCaptions": includeCaptions,
        "segmentCount": segmentCount,
        "cacheMode": cacheMode,
    }
    fp = _fingerprint(TOOL, params)

    # Log api request
    api_requests = _load("api_requests.json")
    req_row = {
        "id": _new_id("ytreq"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fp,
        "cache_mode": cacheMode,
        "cache_hit": False,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    def _persist_req():
        rows = _load("api_requests.json")
        for i, r in enumerate(rows):
            if isinstance(r, dict) and r.get("id") == req_row["id"]:
                rows[i] = req_row
                break
        _save("api_requests.json", rows)

    def _finish(status, response_summary=None, error_code=None, error_message=None, cache_hit=False, quota_cost=0):
        ts = _now_iso()
        req_row["updated_at"] = ts
        if req_row["started_at"] is None:
            req_row["started_at"] = ts
        req_row["status"] = status
        if status in ("succeeded", "failed", "cancelled"):
            req_row["finished_at"] = ts
        req_row["response_summary"] = response_summary
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["cache_hit"] = bool(cache_hit)
        req_row["youtube_quota_cost"] = int(quota_cost) if isinstance(quota_cost, int) and quota_cost >= 0 else 0
        _persist_req()

    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["updated_at"] = req_row["started_at"]
    _persist_req()

    # Cache by prior succeeded request
    if cacheMode in ("read_through", "cache_only"):
        for r in api_requests:
            if isinstance(r, dict) and r.get("tool_name") == TOOL and r.get("status") == "succeeded" and r.get("finished_at") and r.get("request_fingerprint") == fp:
                summary = r.get("response_summary") or {}
                _finish("succeeded", response_summary=summary, cache_hit=True, quota_cost=0)
                return {
                    "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": True, "cache_mode": cacheMode},
                    "results": summary.get("results", []),
                }
        if cacheMode == "cache_only":
            _finish("failed", error_code="NOT_FOUND", error_message="No cached enhanced transcript available in cache_only mode.")
            return _err("NOT_FOUND", "No cached enhanced transcript available in cache_only mode.")

    videos = _load("videos.json")
    vta = _load("video_text_assets.json")
    vid_by_yid = {v.get("youtube_video_id"): v for v in videos if isinstance(v, dict) and v.get("youtube_video_id")}

    def _extract_captions(trans_asset):
        payload = trans_asset.get("payload") if isinstance(trans_asset, dict) else None
        if not isinstance(payload, dict):
            return []
        caps = payload.get("captions")
        if not isinstance(caps, list):
            return []
        cleaned = []
        for c in caps:
            if not isinstance(c, dict):
                continue
            s = _safe_int(c.get("start_ms"))
            d = _safe_int(c.get("duration_ms"))
            txt = c.get("text")
            if s is None or s < 0:
                continue
            if d is not None and d < 0:
                d = None
            if not isinstance(txt, str):
                txt = ""
            cleaned.append({"start_ms": s, "duration_ms": d, "text": txt})
        cleaned.sort(key=lambda x: x["start_ms"])
        return cleaned

    def _filter_window(caps):
        if startMs is None and endMs is None:
            return caps
        out = []
        for c in caps:
            s = c["start_ms"]
            e = s + (c["duration_ms"] if isinstance(c["duration_ms"], int) else 0)
            if startMs is not None and e < startMs:
                continue
            if endMs is not None and s > endMs:
                continue
            out.append(c)
        return out

    def _search_matches(caps):
        if not query:
            return []
        q = query.lower()
        matches = []
        for c in caps:
            if q in (c.get("text") or "").lower():
                matches.append({"start_ms": c["start_ms"], "text": c.get("text")})
        return matches

    def _full_text(caps):
        return " ".join([(c.get("text") or "").strip() for c in caps if isinstance(c.get("text"), str)]).strip()

    def _segments(caps, seg_count):
        if seg_count is None:
            return None
        if not caps:
            return [{"index": i, "start_ms": 0, "end_ms": 0, "text": ""} for i in range(seg_count)]
        last_end = 0
        for c in caps:
            s = c["start_ms"]
            d = c["duration_ms"] if isinstance(c["duration_ms"], int) else 0
            last_end = max(last_end, s + d)
        if last_end <= 0:
            last_end = max(caps[-1]["start_ms"], 1)
        seg_len = max(1, int(math.ceil(last_end / float(seg_count))))
        segs = []
        for i in range(seg_count):
            s0 = i * seg_len
            e0 = min(last_end, (i + 1) * seg_len)
            seg_caps = [c for c in caps if c["start_ms"] >= s0 and c["start_ms"] < e0]
            segs.append({"index": i, "start_ms": s0, "end_ms": e0, "text": _full_text(seg_caps)})
        return segs

    results = []
    quota_cost = 0

    for yid in videoIds:
        v = vid_by_yid.get(yid)
        if not v:
            results.append({"videoId": yid, "error": {"code": "NOT_FOUND", "message": "Video not found in local cache."}})
            continue

        eff_lang = language or v.get("default_language") or "en"

        trans = None
        for a in vta:
            if isinstance(a, dict) and a.get("video_id") == v.get("id") and a.get("asset_type") == "transcript_full" and a.get("language") == eff_lang:
                trans = a
                break
        if trans is None:
            # fallback to any ready transcript_full for offline processing
            for a in vta:
                if isinstance(a, dict) and a.get("video_id") == v.get("id") and a.get("asset_type") == "transcript_full" and a.get("status") == "ready":
                    trans = a
                    eff_lang = a.get("language") or eff_lang
                    break

        if trans is None:
            results.append({"videoId": yid, "language": eff_lang, "error": {"code": "YT_CAPTIONS_DISABLED", "message": "Captions are disabled for this video or not available in the requested language."}})
            continue

        caps = _extract_captions(trans)
        caps = _filter_window(caps)

        matches = _search_matches(caps)
        segs = _segments(caps, segmentCount)

        entry = {
            "videoId": yid,
            "language": eff_lang,
            "assetId": trans.get("id"),
            "matches": matches,
        }
        if includeCaptions:
            entry["captions"] = caps
        if includeFullText:
            entry["fullText"] = _full_text(caps)
        if segmentCount is not None:
            entry["segments"] = segs

            # Persist derived segmented asset when requested and cacheMode != bypass
            if cacheMode != "bypass":
                existing_seg = None
                for a in vta:
                    if isinstance(a, dict) and a.get("video_id") == v.get("id") and a.get("asset_type") == "transcript_segmented" and a.get("language") == eff_lang:
                        existing_seg = a
                        break
                seg_payload = {
                    "segmentCount": segmentCount,
                    "startMs": startMs,
                    "endMs": endMs,
                    "query": query,
                    "segments": segs,
                }
                if existing_seg:
                    # lifecycle transitions: ready->stale or stale->ready etc; here we just update payload and mark ready if allowed
                    cur = existing_seg.get("status")
                    allowed = {"pending": {"ready", "error"}, "ready": {"stale", "error"}, "stale": {"pending", "ready", "error"}, "error": {"pending"}}
                    if cur in allowed and "ready" in allowed[cur]:
                        existing_seg["status"] = "ready"
                    existing_seg["payload"] = seg_payload
                    existing_seg["derived_from_asset_id"] = trans.get("id")
                    existing_seg["source_request_id"] = req_row["id"]
                    existing_seg["fetched_at"] = _now_iso()
                    existing_seg["updated_at"] = _now_iso()
                    for i, a2 in enumerate(vta):
                        if isinstance(a2, dict) and a2.get("id") == existing_seg.get("id"):
                            vta[i] = existing_seg
                            break
                else:
                    vta.append({
                        "id": _new_id("ytxta"),
                        "video_id": v.get("id"),
                        "asset_type": "transcript_segmented",
                        "status": "ready",
                        "language": eff_lang,
                        "sort_order": None,
                        "youtube_comment_id": None,
                        "parent_youtube_comment_id": None,
                        "author_channel_id": None,
                        "published_at": None,
                        "like_count": None,
                        "text": None,
                        "start_ms": None,
                        "duration_ms": None,
                        "payload": seg_payload,
                        "source_request_id": req_row["id"],
                        "derived_from_asset_id": trans.get("id"),
                        "fetched_at": _now_iso(),
                        "created_at": _now_iso(),
                        "updated_at": _now_iso(),
                    })

        results.append(entry)

    # persist derived assets if any were added/updated
    _save("video_text_assets.json", vta)

    summary = {"results": results, "count": len(results)}
    _finish("succeeded", response_summary=summary, cache_hit=False, quota_cost=quota_cost)

    return {
        "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": False, "cache_mode": cacheMode, "latency_ms": int((time.time() - t0) * 1000)},
        "results": results,
    }

def get_key_moments(videoId, maxMoments=None, language=None, cacheMode=None, **_extra):
    import json, os, datetime, time, hashlib, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _canon(v):
        if isinstance(v, dict):
            return {k: _canon(v[k]) for k in sorted(v.keys())}
        if isinstance(v, list):
            return [_canon(x) for x in v]
        return v

    def _fingerprint(tool, params):
        blob = json.dumps({"tool_name": tool, "params": _canon(params)}, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()
    TOOL = "get-key-moments"
    VALID_CACHE = {"bypass", "read_through", "cache_only"}
    SERVER_MAX_MOMENTS = 100  # server-side cap per business rules

    # Validate inputs
    if not isinstance(videoId, str) or not videoId.strip():
        return _err("VALIDATION_ERROR", "videoId must be a non-empty string.", field="videoId")
    videoId = videoId.strip()

    if maxMoments is None:
        maxMoments = 10
    if not isinstance(maxMoments, int) or maxMoments < 1 or maxMoments > 50:
        return _err("VALIDATION_ERROR", "maxMoments must be an integer between 1 and 50.", field="maxMoments")
    if maxMoments > SERVER_MAX_MOMENTS:
        return _err("VALIDATION_ERROR", f"maxMoments must not exceed server limit of {SERVER_MAX_MOMENTS}.", field="maxMoments")

    if language is not None:
        if not isinstance(language, str) or not language.strip():
            return _err("VALIDATION_ERROR", "language must be a non-empty string when provided.", field="language")
        language = language.strip()
        if not re.fullmatch(r"[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*", language):
            return _err("VALIDATION_ERROR", "language must look like a language code (e.g., en, en-US).", field="language")

    if cacheMode is None:
        cacheMode = "read_through"
    if not isinstance(cacheMode, str) or cacheMode not in VALID_CACHE:
        return _err("VALIDATION_ERROR", "cacheMode must be one of: bypass, read_through, cache_only.", field="cacheMode")

    params = {"videoId": videoId, "maxMoments": maxMoments, "language": language, "cacheMode": cacheMode}
    fp = _fingerprint(TOOL, params)

    # Log api request
    api_requests = _load("api_requests.json")
    req_row = {
        "id": _new_id("ytreq"),
        "tool_name": TOOL,
        "status": "queued",
        "request_params": params,
        "request_fingerprint": fp,
        "cache_mode": cacheMode,
        "cache_hit": False,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    def _persist_req():
        rows = _load("api_requests.json")
        for i, r in enumerate(rows):
            if isinstance(r, dict) and r.get("id") == req_row["id"]:
                rows[i] = req_row
                break
        _save("api_requests.json", rows)

    def _finish(status, response_summary=None, error_code=None, error_message=None, cache_hit=False, quota_cost=0):
        ts = _now_iso()
        req_row["updated_at"] = ts
        if req_row["started_at"] is None:
            req_row["started_at"] = ts
        req_row["status"] = status
        if status in ("succeeded", "failed", "cancelled"):
            req_row["finished_at"] = ts
        req_row["response_summary"] = response_summary
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["cache_hit"] = bool(cache_hit)
        req_row["youtube_quota_cost"] = int(quota_cost) if isinstance(quota_cost, int) and quota_cost >= 0 else 0
        _persist_req()

    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["updated_at"] = req_row["started_at"]
    _persist_req()

    # Cache by prior succeeded request
    if cacheMode in ("read_through", "cache_only"):
        for r in api_requests:
            if isinstance(r, dict) and r.get("tool_name") == TOOL and r.get("status") == "succeeded" and r.get("finished_at") and r.get("request_fingerprint") == fp:
                summary = r.get("response_summary") or {}
                _finish("succeeded", response_summary=summary, cache_hit=True, quota_cost=0)
                return {
                    "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": True, "cache_mode": cacheMode},
                    "videoId": videoId,
                    "language": summary.get("language", language),
                    "moments": summary.get("moments", []),
                }
        if cacheMode == "cache_only":
            _finish("failed", error_code="NOT_FOUND", error_message="No cached key moments available in cache_only mode.")
            return _err("NOT_FOUND", "No cached key moments available in cache_only mode.")

    videos = _load("videos.json")
    vta = _load("video_text_assets.json")

    vid_row = None
    for v in videos:
        if isinstance(v, dict) and v.get("youtube_video_id") == videoId:
            vid_row = v
            break
    if not vid_row:
        # for offline store, return empty moments rather than NOT_FOUND
        summary = {"moments": [], "language": language}
        _finish("succeeded", response_summary=summary, cache_hit=False, quota_cost=0)
        return {
            "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": False, "cache_mode": cacheMode, "latency_ms": int((time.time() - t0) * 1000)},
            "videoId": videoId,
            "language": language,
            "moments": [],
        }

    eff_lang = language or vid_row.get("default_language") or "en"

    # Find transcript_full
    trans = None
    for a in vta:
        if isinstance(a, dict) and a.get("video_id") == vid_row.get("id") and a.get("asset_type") == "transcript_full" and a.get("language") == eff_lang:
            trans = a
            break
    if trans is None:
        for a in vta:
            if isinstance(a, dict) and a.get("video_id") == vid_row.get("id") and a.get("asset_type") == "transcript_full" and a.get("status") == "ready":
                trans = a
                eff_lang = a.get("language") or eff_lang
                break
    if trans is None:
        _finish("failed", error_code="YT_CAPTIONS_DISABLED", error_message="Captions are disabled for this video or not available in the requested language.")
        return _err("NOT_FOUND", "Captions are disabled for this video or not available in the requested language.", error_code="YT_CAPTIONS_DISABLED")

    # Check for cached derived key_moments asset unless bypass
    existing = None
    for a in vta:
        if isinstance(a, dict) and a.get("video_id") == vid_row.get("id") and a.get("asset_type") == "key_moments" and a.get("language") == eff_lang:
            existing = a
            break
    if cacheMode != "bypass" and existing and existing.get("status") == "ready":
        payload = existing.get("payload") if isinstance(existing.get("payload"), dict) else {}
        moments = payload.get("moments")
        if not isinstance(moments, list):
            moments = []
        moments = moments[:maxMoments]
        summary = {"moments": moments, "assetId": existing.get("id"), "language": eff_lang}
        _finish("succeeded", response_summary=summary, cache_hit=True, quota_cost=0)
        return {
            "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": True, "cache_mode": cacheMode},
            "videoId": videoId,
            "language": eff_lang,
            "assetId": existing.get("id"),
            "moments": moments,
        }

    # Derive moments from transcript captions (simple heuristic: pick evenly spaced captions)
    payload = trans.get("payload") if isinstance(trans.get("payload"), dict) else {}
    captions = payload.get("captions")
    if not isinstance(captions, list):
        captions = []
    caps = []
    for c in captions:
        if not isinstance(c, dict):
            continue
        s = c.get("start_ms")
        txt = c.get("text")
        if isinstance(s, int) and s >= 0 and isinstance(txt, str) and txt.strip():
            caps.append({"start_ms": s, "text": txt.strip()})
    caps.sort(key=lambda x: x["start_ms"])

    moments = []
    if caps:
        step = max(1, len(caps) // maxMoments)
        idx = 0
        while len(moments) < maxMoments and idx < len(caps):
            c = caps[idx]
            moments.append({"start_ms": c["start_ms"], "title": c["text"][:120], "detail": c["text"]})
            idx += step
    # Ensure maxMoments cap
    moments = moments[:maxMoments]

    # Persist derived key_moments asset (derived_from_asset_id set)
    km_payload = {"moments": moments, "maxMoments": maxMoments}
    if existing:
        cur = existing.get("status")
        allowed = {"pending": {"ready", "error"}, "ready": {"stale", "error"}, "stale": {"pending", "ready", "error"}, "error": {"pending"}}
        if cur in allowed and "ready" in allowed[cur]:
            existing["status"] = "ready"
        existing["payload"] = km_payload
        existing["derived_from_asset_id"] = trans.get("id")
        existing["source_request_id"] = req_row["id"]
        existing["fetched_at"] = _now_iso()
        existing["updated_at"] = _now_iso()
        for i, a2 in enumerate(vta):
            if isinstance(a2, dict) and a2.get("id") == existing.get("id"):
                vta[i] = existing
                break
        asset_id = existing.get("id")
    else:
        asset_id = _new_id("ytxta")
        vta.append({
            "id": asset_id,
            "video_id": vid_row.get("id"),
            "asset_type": "key_moments",
            "status": "ready",
            "language": eff_lang,
            "sort_order": None,
            "youtube_comment_id": None,
            "parent_youtube_comment_id": None,
            "author_channel_id": None,
            "published_at": None,
            "like_count": None,
            "text": None,
            "start_ms": None,
            "duration_ms": None,
            "payload": km_payload,
            "source_request_id": req_row["id"],
            "derived_from_asset_id": trans.get("id"),
            "fetched_at": _now_iso(),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        })
    _save("video_text_assets.json", vta)

    summary = {"moments": moments, "assetId": asset_id, "language": eff_lang}
    _finish("succeeded", response_summary=summary, cache_hit=False, quota_cost=0)

    return {
        "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": False, "cache_mode": cacheMode, "latency_ms": int((time.time() - t0) * 1000)},
        "videoId": videoId,
        "language": eff_lang,
        "assetId": asset_id,
        "moments": moments,
    }

def get_segmented_transcript(videoId, segmentCount=None, language=None, cacheMode=None, **_extra):
