    if segmentCount < 2 or segmentCount > 200:
        return _err("VALIDATION_ERROR", "segmentCount must be between 2 and 200.", field="segmentCount")

    if language is not None:
        if not isinstance(language, str) or not language.strip():
            return _err("VALIDATION_ERROR", "language must be a non-empty string when provided.", field="language")
        language = language.strip()
        if not re.fullmatch(r"[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*", language):
            return _err("VALIDATION_ERROR", "language must look like a language code (e.g., en, en-US).", field="language")

    if cacheMode is None:
        cacheMode = "read_through"
    if not isinstance(cacheMode, str) or cacheMode not in VALID_CACHE:
