        for i, r in enumerate(rows):
            if isinstance(r, dict) and r.get("id") == req_row["id"]:
                rows[i] = req_row
                break
        _save("api_requests.json", rows)

    def _finish(status, response_summary=None, error_code=None, error_message=None, cache_hit=False, quota_cost=0):
        ts = _now_iso()
        req_row["updated_at"] = ts
        if req_row["started_at"] is None:
            req_row["started_at"] = ts
        req_row["status"] = status
        if status in ("succeeded", "failed", "cancelled"):
            req_row["finished_at"] = ts
        req_row["response_summary"] = response_summary
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["cache_hit"] = bool(cache_hit)
        req_row["youtube_quota_cost"] = int(quota_cost) if isinstance(quota_cost, int) and quota_cost >= 0 else 0
        _persist_req()

    req_row["status"] = "running"
    req_row["started_at"] = _now_iso()
    req_row["updated_at"] = req_row["started_at"]
    _persist_req()

    # Cache by prior succeeded request
    if cacheMode in ("read_through", "cache_only"):
        for r in api_requests:
            if isinstance(r, dict) and r.get("tool_name") == TOOL and r.get("status") == "succeeded" and r.get("finished_at") and r.get("request_fingerprint") == fp:
                summary = r.get("response_summary") or {}
                _finish("succeeded", response_summary=summary, cache_hit=True, quota_cost=0)
                return {
                    "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": True, "cache_mode": cacheMode},
                    "videoId": videoId,
                    "language": summary.get("language", language),
                    "segmentCount": segmentCount,
                    "segments": summary.get("segments", []),
                }
        if cacheMode == "cache_only":
            _finish("failed", error_code="NOT_FOUND", error_message="No cached segmented transcript available in cache_only mode.")
            return _err("NOT_FOUND", "No cached segmented transcript available in cache_only mode.")

    videos = _load("videos.json")
    vta = _load("video_text_assets.json")

    vid_row = None
    for v in videos:
        if isinstance(v, dict) and v.get("youtube_video_id") == videoId:
            vid_row = v
            break
    if not vid_row:
        # return empty segments as a normal empty read result
        segs = [{"index": i, "start_ms": 0, "end_ms": 0, "text": ""} for i in range(segmentCount)]
        summary = {"segments": segs, "language": language, "segmentCount": segmentCount}
        _finish("succeeded", response_summary=summary, cache_hit=False, quota_cost=0)
        return {
            "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": False, "cache_mode": cacheMode, "latency_ms": int((time.time() - t0) * 1000)},
            "videoId": videoId,
            "language": language,
            "segmentCount": segmentCount,
            "segments": segs,
        }

    eff_lang = language or vid_row.get("default_language") or "en"

    # Find transcript_full
    trans = None
    for a in vta:
        if isinstance(a, dict) and a.get("video_id") == vid_row.get("id") and a.get("asset_type") == "transcript_full" and a.get("language") == eff_lang:
            trans = a
            break
    if trans is None:
        for a in vta:
            if isinstance(a, dict) and a.get("video_id") == vid_row.get("id") and a.get("asset_type") == "transcript_full" and a.get("status") == "ready":
                trans = a
                eff_lang = a.get("language") or eff_lang
                break
    if trans is None:
        _finish("failed", error_code="YT_CAPTIONS_DISABLED", error_message="Captions are disabled for this video or not available in the requested language.")
        return _err("NOT_FOUND", "Captions are disabled for this video or not available in the requested language.", error_code="YT_CAPTIONS_DISABLED")

    # Cached derived transcript_segmented asset if ready and not bypass
    existing = None
    for a in vta:
        if isinstance(a, dict) and a.get("video_id") == vid_row.get("id") and a.get("asset_type") == "transcript_segmented" and a.get("language") == eff_lang:
            existing = a
            break
    if cacheMode != "bypass" and existing and existing.get("status") == "ready":
        payload = existing.get("payload") if isinstance(existing.get("payload"), dict) else {}
        if payload.get("segmentCount") == segmentCount:
            segs = payload.get("segments")
            if isinstance(segs, list):
                summary = {"segments": segs, "assetId": existing.get("id"), "language": eff_lang, "segmentCount": segmentCount}
                _finish("succeeded", response_summary=summary, cache_hit=True, quota_cost=0)
                return {
                    "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": True, "cache_mode": cacheMode},
                    "videoId": videoId,
                    "language": eff_lang,
                    "assetId": existing.get("id"),
                    "segmentCount": segmentCount,
                    "segments": segs,
                }

    # compute segments from captions
    payload = trans.get("payload") if isinstance(trans.get("payload"), dict) else {}
    captions = payload.get("captions")
    if not isinstance(captions, list):
        captions = []
    caps = []
    last_end = 0
    for c in captions:
        if not isinstance(c, dict):
            continue
        s = c.get("start_ms")
        d = c.get("duration_ms")
        txt = c.get("text")
        if isinstance(s, int) and s >= 0:
            if not isinstance(d, int) or d < 0:
                d = 0
            if not isinstance(txt, str):
                txt = ""
            caps.append({"start_ms": s, "duration_ms": d, "text": txt})
            last_end = max(last_end, s + d)
    caps.sort(key=lambda x: x["start_ms"])
    if last_end <= 0:
        last_end = max((caps[-1]["start_ms"] if caps else 0), 1)

    seg_len = max(1, int(math.ceil(last_end / float(segmentCount))))
    segs = []
    for i in range(segmentCount):
        s0 = i * seg_len
        e0 = min(last_end, (i + 1) * seg_len)
        seg_caps = [c for c in caps if c["start_ms"] >= s0 and c["start_ms"] < e0]
        text = " ".join([(c.get("text") or "").strip() for c in seg_caps if isinstance(c.get("text"), str)]).strip()
        segs.append({"index": i, "start_ms": s0, "end_ms": e0, "text": text})

    # persist derived segmentation with parameters
    seg_payload = {"segmentCount": segmentCount, "segments": segs}
    if existing:
        cur = existing.get("status")
        allowed = {"pending": {"ready", "error"}, "ready": {"stale", "error"}, "stale": {"pending", "ready", "error"}, "error": {"pending"}}
        if cur in allowed and "ready" in allowed[cur]:
            existing["status"] = "ready"
        existing["payload"] = seg_payload
        existing["derived_from_asset_id"] = trans.get("id")
        existing["source_request_id"] = req_row["id"]
        existing["fetched_at"] = _now_iso()
        existing["updated_at"] = _now_iso()
        for i, a2 in enumerate(vta):
            if isinstance(a2, dict) and a2.get("id") == existing.get("id"):
                vta[i] = existing
                break
        asset_id = existing.get("id")
    else:
        asset_id = _new_id("ytxta")
        vta.append({
            "id": asset_id,
            "video_id": vid_row.get("id"),
            "asset_type": "transcript_segmented",
            "status": "ready",
            "language": eff_lang,
            "sort_order": None,
            "youtube_comment_id": None,
            "parent_youtube_comment_id": None,
            "author_channel_id": None,
            "published_at": None,
            "like_count": None,
            "text": None,
            "start_ms": None,
            "duration_ms": None,
            "payload": seg_payload,
            "source_request_id": req_row["id"],
            "derived_from_asset_id": trans.get("id"),
            "fetched_at": _now_iso(),
            "created_at": _now_iso(),
            "updated_at": _now_iso(),
        })
    _save("video_text_assets.json", vta)

    summary = {"segments": segs, "assetId": asset_id, "language": eff_lang, "segmentCount": segmentCount}
    _finish("succeeded", response_summary=summary, cache_hit=False, quota_cost=0)

    return {
        "request": {"id": req_row["id"], "status": "succeeded", "cache_hit": False, "cache_mode": cacheMode, "latency_ms": int((time.time() - t0) * 1000)},
        "videoId": videoId,
        "language": eff_lang,
        "assetId": asset_id,
        "segmentCount": segmentCount,
        "segments": segs,
    }

def list_api_requests(status=None, toolName=None, requestFingerprint=None, cacheHit=None, createdAfter=None, createdBefore=None, finishedAfter=None, finishedBefore=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string.", field=field)
        ss = s.strip()
        if not ss:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string.", field=field)
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1])
                return dt, None
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt, None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO-8601 date-time string.", field=field)

    def _row_dt(val):
        if not isinstance(val, str) or not val.strip():
            return None
        ss = val.strip()
        try:
            if ss.endswith("Z"):
                return datetime.datetime.fromisoformat(ss[:-1])
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except ValueError:
            return None

    def _canonical(o):
        if o is None:
            return None
        if isinstance(o, bool):
            return o
        if isinstance(o, (int, float, str)):
            return o
        if isinstance(o, list):
            return [_canonical(x) for x in o]
        if isinstance(o, dict):
            return {k: _canonical(o[k]) for k in sorted(o.keys())}
        return str(o)

    def _fingerprint(tool, params):
        payload = {"tool_name": tool, "request_params": _canonical(params)}
        s = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":"), sort_keys=True).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        # Relaxed: accept string cursor (opaque) OR integer cursor (legacy callers), per audit
        if cur is None:
            return 0, None
        if isinstance(cur, int):
            if cur < 0:
                return None, _err("VALIDATION_ERROR", "cursor must be >= 0 when provided as an integer.", field="cursor")
            return cur, None
        if not isinstance(cur, str):
            return None, _err("VALIDATION_ERROR", "cursor must be a string or integer when provided.", field="cursor")
        s = cur.strip()
        if s == "":
            return 0, None
        # allow plain integer string too
        if s.isdigit():
            return int(s), None
        # try base64 json {"offset": n}
        try:
            pad = "=" * (-len(s) % 4)
            data = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            obj = json.loads(data.decode("utf-8"))
            off = obj.get("offset", 0)
            if not isinstance(off, int) or off < 0:
                return None, _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")
            return off, None
        except Exception:
            # opaque cursor we don't understand -> validation error
            return None, _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    STATUS_ENUM = {"queued", "running", "succeeded", "failed", "cancelled"}

    t0 = time.time()
    tool = "list-api-requests"
    params_for_log = {
        "status": status,
        "toolName": toolName,
        "requestFingerprint": requestFingerprint,
        "cacheHit": cacheHit,
        "createdAfter": createdAfter,
        "createdBefore": createdBefore,
        "finishedAfter": finishedAfter,
        "finishedBefore": finishedBefore,
        "limit": limit,
        "cursor": cursor,
    }

    # Create api_requests row for this call (must reach terminal)
    api_requests = _load("api_requests.json")
    now = _now_iso()

    # generate id with ytreq_ + time-based component
    ts_part = datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f")
    new_id = "ytreq_" + ts_part
    # ensure uniqueness
    existing_ids = {r.get("id") for r in api_requests if isinstance(r, dict)}
    if new_id in existing_ids:
        new_id = "ytreq_" + ts_part + "_1"

    req_row = {
        "id": new_id,
        "tool_name": tool,
        "status": "queued",
        "request_params": params_for_log,
        "request_fingerprint": _fingerprint(tool, params_for_log),
        "cache_mode": "bypass",
        "cache_hit": False,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    def _persist_req(updated):
        rows = _load("api_requests.json")
        for i, r in enumerate(rows):
            if isinstance(r, dict) and r.get("id") == updated["id"]:
                rows[i] = updated
                _save("api_requests.json", rows)
                return
        rows.append(updated)
        _save("api_requests.json", rows)

    def _finish_ok(summary, cache_hit=False):
        ts = _now_iso()
        req_row["updated_at"] = ts
        if req_row["started_at"] is None:
            req_row["started_at"] = ts
        req_row["status"] = "succeeded"
        req_row["finished_at"] = ts
        req_row["response_summary"] = summary
        req_row["cache_hit"] = bool(cache_hit)
        _persist_req(req_row)

    def _finish_err(err_obj):
        ts = _now_iso()
        req_row["updated_at"] = ts
        if req_row["started_at"] is None:
            req_row["started_at"] = ts
        req_row["status"] = "failed"
        req_row["finished_at"] = ts
        e = err_obj.get("error", {}) if isinstance(err_obj, dict) else {}
        req_row["error_code"] = e.get("code")
        req_row["error_message"] = e.get("message")
        req_row["response_summary"] = {"error": {"code": req_row["error_code"], "message": req_row["error_message"]}}
        _persist_req(req_row)

    # Validate inputs (relaxed to parameter schema; do NOT validate toolName enum)
    if status is not None:
        if not isinstance(status, str):
            err = _err("VALIDATION_ERROR", "status must be a string when provided.", field="status")
            _finish_err(err)
            return err
        if status not in STATUS_ENUM:
            err = _err("VALIDATION_ERROR", "status must be one of queued, running, succeeded, failed, cancelled.", field="status")
            _finish_err(err)
            return err

    if toolName is not None and not isinstance(toolName, str):
        err = _err("VALIDATION_ERROR", "toolName must be a string when provided.", field="toolName")
        _finish_err(err)
        return err

    if requestFingerprint is not None and not isinstance(requestFingerprint, str):
        err = _err("VALIDATION_ERROR", "requestFingerprint must be a string when provided.", field="requestFingerprint")
        _finish_err(err)
        return err

    if cacheHit is not None and not isinstance(cacheHit, bool):
        err = _err("VALIDATION_ERROR", "cacheHit must be a boolean when provided.", field="cacheHit")
        _finish_err(err)
        return err

    created_after_dt, err = _parse_dt(createdAfter, "createdAfter")
    if err:
        _finish_err(err)
        return err
    created_before_dt, err = _parse_dt(createdBefore, "createdBefore")
    if err:
        _finish_err(err)
        return err
    finished_after_dt, err = _parse_dt(finishedAfter, "finishedAfter")
    if err:
        _finish_err(err)
        return err
    finished_before_dt, err = _parse_dt(finishedBefore, "finishedBefore")
    if err:
        _finish_err(err)
        return err

    if limit is None:
        limit_i = 50
    else:
        if not isinstance(limit, int):
            err = _err("VALIDATION_ERROR", "limit must be an integer when provided.", field="limit")
            _finish_err(err)
            return err
        if limit < 1 or limit > 200:
            err = _err("VALIDATION_ERROR", "limit must be between 1 and 200.", field="limit")
            _finish_err(err)
            return err
        limit_i = limit

    offset, err = _decode_cursor(cursor)
    if err:
        _finish_err(err)
        return err

    # Read + filter. Important: api_requests.json contains our own log row too; include it if it matches.
    rows = _load("api_requests.json")
    if not isinstance(rows, list):
        rows = []

    def _match(r):
        if not isinstance(r, dict):
            return False
        if status is not None and r.get("status") != status:
            return False
        if toolName is not None and r.get("tool_name") != toolName:
            return False
        if requestFingerprint is not None and r.get("request_fingerprint") != requestFingerprint:
            return False
        if cacheHit is not None and bool(r.get("cache_hit")) != bool(cacheHit):
            return False

        ca = _row_dt(r.get("created_at"))
        if created_after_dt is not None:
            if ca is None or ca < created_after_dt:
                return False
        if created_before_dt is not None:
            if ca is None or ca >= created_before_dt:
                return False

        fa = _row_dt(r.get("finished_at"))
        if finished_after_dt is not None:
            if fa is None or fa < finished_after_dt:
                return False
        if finished_before_dt is not None:
            if fa is None or fa >= finished_before_dt:
                return False

        return True

    filtered = [r for r in rows if _match(r)]

    # Order most recent first by created_at then id (stable)
    def _sort_key(r):
        dt = _row_dt(r.get("created_at"))
        # None sorts last
        return (dt is None, dt if dt is not None else datetime.datetime.min, r.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    if offset > total:
        offset = total

    page = filtered[offset: offset + limit_i]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor(next_offset) if has_more else None

    summary = {"returned": len(page), "total": total, "has_more": has_more}
    _finish_ok(summary, cache_hit=False)

    # Return envelope
    return {
        "object": "list",
        "data": page,
        "total": total,
        "limit": limit_i,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "cursor": _encode_cursor(offset) if offset else None,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_api_request(id, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "Invalid id.", field="id")

    # Record this call
    api_requests = _load("api_requests.json")
    req_id = "req_" + hashlib.sha256((now + "|get-api-request|" + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:24]
    created_at = now
    req_row = {
        "id": req_id,
        "tool_name": "get-api-request",
        "status": "running",
        "request_params": {"id": id},
        "request_fingerprint": hashlib.sha256(json.dumps({"tool":"get-api-request","params":{"id": id}}, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).hexdigest(),
        "cache_mode": "bypass",
        "cache_hit": False,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": now,
        "finished_at": None,
        "created_at": created_at,
        "updated_at": created_at
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    # Fetch
    rows = _load("api_requests.json")
    found = None
    for r in rows:
        if isinstance(r, dict) and r.get("id") == id:
            found = r
            break

    api_requests = _load("api_requests.json")
    for r in api_requests:
        if r.get("id") == req_id:
            if found is None:
                r["status"] = "failed"
                r["error_code"] = "NOT_FOUND"
                r["error_message"] = "api_requests row not found."
                r["response_summary"] = {"id": id, "found": False}
            else:
                r["status"] = "succeeded"
                r["response_summary"] = {"id": id, "found": True}
            r["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            r["updated_at"] = r["finished_at"]
            break
    _save("api_requests.json", api_requests)

    if found is None:
        return _err("NOT_FOUND", "api_requests row not found.", id=id, request_id=req_id, latency_ms=int((time.time() - t0) * 1000))

    return {"data": found, "request_id": req_id, "latency_ms": int((time.time() - t0) * 1000)}

def cancel_api_request(id, reason=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _canonical(o):
        if o is None or isinstance(o, (bool, int, float, str)):
            return o
        if isinstance(o, list):
            return [_canonical(x) for x in o]
        if isinstance(o, dict):
            return {k: _canonical(o[k]) for k in sorted(o.keys())}
        return str(o)

    def _fingerprint(tool, params):
        payload = {"tool_name": tool, "request_params": _canonical(params)}
        s = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _gen_req_id(existing_ids):
        # ULID-ish, monotonic enough; keep ytreq_ prefix consistent with store
        ts = datetime.datetime.utcnow().strftime("%y%m%d%H%M%S%f")
        base = f"ytreq_{ts}"
        cand = base
        i = 1
        while cand in existing_ids:
            i += 1
            cand = f"{base}_{i}"
        return cand

    t0 = time.time()
    tool = "cancel-api-request"
    params_for_log = {"id": id, "reason": reason}

    api_requests = _load("api_requests.json")
    if isinstance(api_requests, dict) and "rows" in api_requests and isinstance(api_requests.get("rows"), list):
        api_requests_rows = api_requests["rows"]
        api_requests_container = api_requests
    elif isinstance(api_requests, list):
        api_requests_rows = api_requests
        api_requests_container = None
    else:
        api_requests_rows = []
        api_requests_container = None

    now = _now_iso()
    existing_ids = {r.get("id") for r in api_requests_rows if isinstance(r, dict) and r.get("id")}
    req_id = _gen_req_id(existing_ids)
    fp = _fingerprint(tool, params_for_log)

    def _persist_requests():
        if api_requests_container is not None:
            api_requests_container["rows"] = api_requests_rows
            _save("api_requests.json", api_requests_container)
        else:
            _save("api_requests.json", api_requests_rows)

    # Create the api_requests audit row first (must exist even if validation fails)
    req_row = {
        "id": req_id,
        "tool_name": tool,
        "status": "running",
        "request_params": params_for_log,
        "request_fingerprint": fp,
        "cache_mode": "bypass",
        "cache_hit": False,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": now,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    api_requests_rows.append(req_row)
    _persist_requests()

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        req_row["status"] = "failed"
        req_row["error_code"] = "VALIDATION_ERROR"
        req_row["error_message"] = "Parameter 'id' must be a non-empty string."
        req_row["response_summary"] = {"cancelled": False}
        req_row["finished_at"] = _now_iso()
        req_row["updated_at"] = req_row["finished_at"]
        _persist_requests()
        return _err("VALIDATION_ERROR", req_row["error_message"], id=id)

    if reason is not None and not isinstance(reason, str):
        req_row["status"] = "failed"
        req_row["error_code"] = "VALIDATION_ERROR"
        req_row["error_message"] = "Parameter 'reason' must be a string when provided."
        req_row["response_summary"] = {"cancelled": False}
        req_row["finished_at"] = _now_iso()
        req_row["updated_at"] = req_row["finished_at"]
        _persist_requests()
        return _err("VALIDATION_ERROR", req_row["error_message"], reason_type=str(type(reason)))

    # Find target row
    target = None
    for r in api_requests_rows:
        if isinstance(r, dict) and r.get("id") == id:
            target = r
            break

    if target is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "NOT_FOUND"
        req_row["error_message"] = "api_requests row not found."
        req_row["response_summary"] = {"cancelled": False, "id": id}
        req_row["finished_at"] = _now_iso()
        req_row["updated_at"] = req_row["finished_at"]
        _persist_requests()
        return _err("NOT_FOUND", req_row["error_message"], id=id)

    current_status = target.get("status")
    allowed_from = ["queued", "running"]

    # Real-world cancellation semantics: if already cancelled, treat as idempotent success.
    if current_status == "cancelled":
        req_row["status"] = "succeeded"
        req_row["response_summary"] = {"cancelled": True, "id": id, "already_cancelled": True}
        req_row["finished_at"] = _now_iso()
        req_row["updated_at"] = req_row["finished_at"]
        _persist_requests()
        return {
            "id": id,
            "status": "cancelled",
            "cancelled": True,
            "already_cancelled": True,
        }

    # Terminal states are not cancellable; enforce lifecycle rule
    if current_status not in allowed_from:
        req_row["status"] = "failed"
        req_row["error_code"] = "INVALID_TRANSITION"
        req_row["error_message"] = (
            "Cancellation is only allowed when status is queued or running (api_requests lifecycle rule)."
        )
        req_row["response_summary"] = {
            "cancelled": False,
            "id": id,
            "current_status": current_status,
            "allowed_from": allowed_from,
        }
        req_row["finished_at"] = _now_iso()
        req_row["updated_at"] = req_row["finished_at"]
        _persist_requests()
        return _err(
            "INVALID_TRANSITION",
            req_row["error_message"],
            id=id,
            current_status=current_status,
            allowed_from=allowed_from,
        )

    # Apply cancellation
    target["status"] = "cancelled"
    if target.get("started_at") is None:
        target["started_at"] = now
    target["finished_at"] = _now_iso()
    target["updated_at"] = target["finished_at"]
    # store reason in response_summary for auditability without altering schema
    rs = target.get("response_summary")
    if not isinstance(rs, dict):
        rs = {} if rs is None else {"previous": rs}
    if isinstance(reason, str) and reason.strip():
        rs["cancel_reason"] = reason.strip()
    rs["cancelled_by_tool_request_id"] = req_id
    target["response_summary"] = rs

    req_row["status"] = "succeeded"
    req_row["response_summary"] = {"cancelled": True, "id": id}
    req_row["finished_at"] = _now_iso()
    req_row["updated_at"] = req_row["finished_at"]
    _persist_requests()

    # include latency for observability inside response_summary (schema doesn't have field)
    try:
        latency_ms = int((time.time() - t0) * 1000)
        req_row_rs = req_row.get("response_summary") or {}
        if isinstance(req_row_rs, dict):
            req_row_rs["latency_ms"] = latency_ms
            req_row["response_summary"] = req_row_rs
            req_row["updated_at"] = _now_iso()
            _persist_requests()
    except Exception:
        # do not fail the call on observability enrichment
        pass

    return {
        "id": id,
        "status": "cancelled",
        "cancelled": True,
    }

def list_video_text_assets(videoId=None, assetType=None, status=None, language=None, derivedFromAssetId=None, sourceRequestId=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    ASSET_ENUM = ["transcript_full", "transcript_segmented", "key_moments", "comment_thread", "comment"]
    STATUS_ENUM = ["pending", "ready", "stale", "error"]

    # Validate
    if videoId is not None and (not isinstance(videoId, str) or not videoId.strip()):
        return _err("VALIDATION_ERROR", "Invalid videoId.", field="videoId")
    if assetType is not None:
        if not isinstance(assetType, str) or assetType not in ASSET_ENUM:
            return _err("VALIDATION_ERROR", "Invalid assetType.", field="assetType")
    if status is not None:
        if not isinstance(status, str) or status not in STATUS_ENUM:
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if language is not None and (not isinstance(language, str) or not language.strip()):
        return _err("VALIDATION_ERROR", "Invalid language.", field="language")
    if derivedFromAssetId is not None and (not isinstance(derivedFromAssetId, str) or not derivedFromAssetId.strip()):
        return _err("VALIDATION_ERROR", "Invalid derivedFromAssetId.", field="derivedFromAssetId")
    if sourceRequestId is not None and (not isinstance(sourceRequestId, str) or not sourceRequestId.strip()):
        return _err("VALIDATION_ERROR", "Invalid sourceRequestId.", field="sourceRequestId")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit; must be 1..200.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Resolve videoId (youtube_video_id) -> videos.id if filter provided
    internal_video_id = None
    if videoId is not None:
        vids = _load("videos.json")
        for v in vids:
            if isinstance(v, dict) and v.get("youtube_video_id") == videoId:
                internal_video_id = v.get("id")
                break
        if internal_video_id is None:
            # Valid request; empty set
            internal_video_id = "__none__"

    # Decode cursor
    def _dt_from_row(v):
        if not v or not isinstance(v, str):
            return None
        try:
            ss = v.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except ValueError:
            return None

    cursor_created = None
    cursor_id = None
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict) or "created_at" not in obj or "id" not in obj:
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            cursor_created = _dt_from_row(obj["created_at"])
            cursor_id = obj["id"]
            if cursor_created is None or not isinstance(cursor_id, str):
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        except (ValueError, json.JSONDecodeError):
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Record this call
    api_requests = _load("api_requests.json")
    req_id = "req_" + hashlib.sha256((now + "|list-video-text-assets|" + os.urandom(8).hex()).encode("utf-8")).hexdigest()[:24]
    created_at = now
    req_row = {
        "id": req_id,
        "tool_name": "list-video-text-assets",
        "status": "running",
        "request_params": {
            "videoId": videoId, "assetType": assetType, "status": status, "language": language,
            "derivedFromAssetId": derivedFromAssetId, "sourceRequestId": sourceRequestId,
            "limit": limit, "cursor": cursor
        },
        "request_fingerprint": hashlib.sha256(json.dumps({"tool":"list-video-text-assets","params":{
            "videoId": videoId, "assetType": assetType, "status": status, "language": language,
            "derivedFromAssetId": derivedFromAssetId, "sourceRequestId": sourceRequestId,
            "limit": limit, "cursor": cursor
        }}, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).hexdigest(),
        "cache_mode": "bypass",
        "cache_hit": False,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": now,
        "finished_at": None,
        "created_at": created_at,
        "updated_at": created_at
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    assets = _load("video_text_assets.json")

    def _match(a):
        if not isinstance(a, dict):
            return False
        if internal_video_id is not None and a.get("video_id") != internal_video_id:
            return False
        if assetType is not None and a.get("asset_type") != assetType:
            return False
        if status is not None and a.get("status") != status:
            return False
        if language is not None and a.get("language") != language:
            return False
        if derivedFromAssetId is not None and a.get("derived_from_asset_id") != derivedFromAssetId:
            return False
        if sourceRequestId is not None and a.get("source_request_id") != sourceRequestId:
            return False
        return True

    filtered = [a for a in assets if _match(a)]

    # Order newest first: created_at desc, id desc
    def _sort_key(a):
        dt = _dt_from_row(a.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1)
        return (dt, str(a.get("id", "")))
    filtered.sort(key=_sort_key, reverse=True)

    # Apply cursor
    if cursor_created is not None and cursor_id is not None:
        def _after_cursor(a):
            dt = _dt_from_row(a.get("created_at"))
            if dt is None:
                dt = datetime.datetime(1970, 1, 1)
            aid = str(a.get("id", ""))
            if dt < cursor_created:
                return True
            if dt == cursor_created and aid < cursor_id:
                return True
            return False
        filtered = [a for a in filtered if _after_cursor(a)]

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    # Finish audit row
    api_requests = _load("api_requests.json")
    for r in api_requests:
        if r.get("id") == req_id:
            r["status"] = "succeeded"
            r["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            r["updated_at"] = r["finished_at"]
            r["response_summary"] = {"count": len(page), "total": len(filtered), "has_more": has_more}
            break
    _save("api_requests.json", api_requests)

    return {
        "data": page,
        "meta": {"limit": limit, "total": len(filtered), "has_more": has_more, "next_cursor": next_cursor},
        "request_id": req_id,
        "latency_ms": int((time.time() - t0) * 1000)
    }

def get_video_text_asset(id, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0304000" if __import__("os").path.isdir("./environment_mix/0304000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _canonical(o):
        if o is None or isinstance(o, (bool, int, float, str)):
            return o
        if isinstance(o, list):
            return [_canonical(x) for x in o]
        if isinstance(o, dict):
            return {k: _canonical(o[k]) for k in sorted(o.keys())}
        return str(o)

    def _fingerprint(tool, params):
        payload = {"tool_name": tool, "request_params": _canonical(params)}
        s = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), sort_keys=True)
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _gen_req_id(existing_ids):
        ts = datetime.datetime.utcnow().strftime("%y%m%d%H%M%S%f")
        base = f"ytreq_{ts}"
        cand = base
        i = 1
        while cand in existing_ids:
            i += 1
            cand = f"{base}_{i}"
        return cand

    t0 = time.time()
    tool = "get-video-text-asset"
    params_for_log = {"id": id}

    api_requests = _load("api_requests.json")
    if isinstance(api_requests, dict) and "rows" in api_requests and isinstance(api_requests.get("rows"), list):
        api_requests_rows = api_requests["rows"]
        api_requests_container = api_requests
    elif isinstance(api_requests, list):
        api_requests_rows = api_requests
        api_requests_container = None
    else:
        api_requests_rows = []
        api_requests_container = None

    now = _now_iso()
    existing_ids = {r.get("id") for r in api_requests_rows if isinstance(r, dict) and r.get("id")}
    req_id = _gen_req_id(existing_ids)
    fp = _fingerprint(tool, params_for_log)

    def _persist_requests():
        if api_requests_container is not None:
            api_requests_container["rows"] = api_requests_rows
            _save("api_requests.json", api_requests_container)
        else:
            _save("api_requests.json", api_requests_rows)

    # Create audit row first
    req_row = {
        "id": req_id,
        "tool_name": tool,
        "status": "running",
        "request_params": params_for_log,
        "request_fingerprint": fp,
        "cache_mode": "bypass",
        "cache_hit": False,
        "response_summary": None,
        "error_code": None,
        "error_message": None,
        "youtube_quota_cost": 0,
        "started_at": now,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    api_requests_rows.append(req_row)
    _persist_requests()

    # Validate input
    if not isinstance(id, str) or not id.strip():
        req_row["status"] = "failed"
        req_row["error_code"] = "VALIDATION_ERROR"
        req_row["error_message"] = "Parameter 'id' must be a non-empty string."
        req_row["response_summary"] = {"found": False}
        req_row["finished_at"] = _now_iso()
        req_row["updated_at"] = req_row["finished_at"]
        _persist_requests()
        return _err("VALIDATION_ERROR", req_row["error_message"], id=id)

    # Load assets and find by id (no extra context required)
    assets = _load("video_text_assets.json")
    if isinstance(assets, dict) and "rows" in assets and isinstance(assets.get("rows"), list):
        assets_rows = assets["rows"]
    elif isinstance(assets, list):
        assets_rows = assets
    else:
        assets_rows = []

    found = None
    for r in assets_rows:
        if isinstance(r, dict) and r.get("id") == id:
            found = r
            break

    if found is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "NOT_FOUND"
        req_row["error_message"] = "video_text_assets row not found."
        req_row["response_summary"] = {"found": False, "id": id}
        req_row["finished_at"] = _now_iso()
        req_row["updated_at"] = req_row["finished_at"]
        _persist_requests()
        return _err("NOT_FOUND", req_row["error_message"], id=id)

    req_row["status"] = "succeeded"
    req_row["response_summary"] = {
        "found": True,
        "id": id,
        "asset_type": found.get("asset_type"),
        "status": found.get("status"),
        "video_id": found.get("video_id"),
    }
    req_row["finished_at"] = _now_iso()
    req_row["updated_at"] = req_row["finished_at"]
    _persist_requests()

    try:
        latency_ms = int((time.time() - t0) * 1000)
        rs = req_row.get("response_summary") or {}
        if isinstance(rs, dict):
            rs["latency_ms"] = latency_ms
            req_row["response_summary"] = rs
            req_row["updated_at"] = _now_iso()
            _persist_requests()
    except Exception:
        pass

    # Return the stored row (do not fabricate fields)
    return {"video_text_asset": found}
